        "pt": "Sarah trabalha para uma ONG internacional. Ela está preparando uma apresentação para persuadir potenciais doadores a financiar um novo projeto que aborda as disparidades na saúde global. Ela precisa destacar o impacto severo dessas questões e propor soluções eficazes."
