          "en": "The evidence suggests that lack of access to basic healthcare can trigger a cascade of negative consequences, from reduced productivity to increased poverty. It really paves the way for further instability.",
          "pt": "As evidências sugerem que a falta de acesso à saúde básica pode desencadear uma cascata de consequências negativas, desde a produtividade reduzida ao aumento da pobreza. Isso realmente abre caminho para uma maior instabilidade."
