        "pt": "A líder de equipe, Elena, está discutindo um novo projeto desafiador com seu colega, Mark. O projeto exige uma mudança significativa em sua abordagem usual, e Elena quer garantir que eles adotem uma mentalidade produtiva enquanto reconhecem as dificuldades potenciais."
