    "grammar": [
      {
        "title": {
          "en": "Discourse markers for balancing perspectives",
          "pt": "Marcadores discursivos para equilibrar perspectivas"
        },
        "examples": [
          {
            "en": "Admittedly, the plan has some flaws, but its benefits outweigh them.",
            "pt": "É certo que o plano tem algumas falhas, mas seus benefícios as superam."
          },
          {
            "en": "All things considered, it was a successful launch despite the minor technical glitches.",
            "pt": "Considerando tudo, foi um lançamento bem-sucedido, apesar dos pequenos problemas técnicos."
          },
          {
            "en": "The new policy is unpopular. That being said, it is necessary for long-term stability.",
            "pt": "A nova política é impopular. Dito isso, é necessária para a estabilidade a longo prazo."
          }
        ],
        "rule": {
          "en": "Discourse markers like 'admittedly,' 'that being said,' and 'all things considered' are used to introduce a contrasting or balancing point, often to acknowledge a negative aspect before presenting a positive one, or to offer a summary conclusion based on various factors. They help in presenting a nuanced and balanced argument or opinion.",
          "pt": "Marcadores discursivos como 'admittedly' (é certo que), 'that being said' (dito isso) e 'all things considered' (considerando tudo) são usados para introduzir um ponto contrastante ou equilibrador, muitas vezes para reconhecer um aspecto negativo antes de apresentar um positivo, ou para oferecer uma conclusão resumida com base em vários fatores. Eles ajudam a apresentar um argumento ou opinião matizada e equilibrada."
        },
        "mistakes": [
          {
            "en": "Using 'admittedly' to introduce a purely positive statement without any preceding or subsequent contrast.",
            "pt": "Usar 'admittedly' para introduzir uma afirmação puramente positiva sem qualquer contraste precedente ou subsequente."
          },
          {
            "en": "Confusing 'that being said' with simply 'however' when a concession or prior point needs to be acknowledged.",
            "pt": "Confundir 'that being said' com apenas 'however' quando uma concessão ou ponto anterior precisa ser reconhecido."
          }
        ]
      }
    ],
