    "grammar": [
      {
        "title": {
          "en": "Idiomatic Expressions for Describing Risk and Opportunity",
          "pt": "Expressões Idiomáticas para Descrever Risco e Oportunidade"
        },
        "examples": [
          {
            "en": "Starting a new gallery in this economy is a calculated risk.",
            "pt": "Abrir uma nova galeria nesta economia é um risco calculado."
          },
          {
            "en": "The sudden funding offers a golden opportunity for our project.",
            "pt": "O financiamento repentino oferece uma oportunidade de ouro para nosso projeto."
          },
          {
            "en": "We took a gamble by casting an unknown actor, but it paid off.",
            "pt": "Arriscamos ao escalar um ator desconhecido, mas valeu a pena."
          }
        ],
        "rule": {
          "en": "Idiomatic expressions related to risk and opportunity are fixed phrases used to describe situations involving uncertainty or potential for success. They are often informal but common in business and casual conversation. 'A calculated risk' means a risk taken after careful consideration, where the potential benefits outweigh the potential losses. 'A golden opportunity' refers to an excellent chance that may not come again. 'To take a gamble' means to take a risk, often with uncertain results. 'To pay off' means to yield a positive result.",
          "pt": "Expressões idiomáticas relacionadas a risco e oportunidade são frases fixas usadas para descrever situações que envolvem incerteza ou potencial de sucesso. Elas são frequentemente informais, mas comuns em conversas de negócios e casuais. 'A calculated risk' significa um risco assumido após cuidadosa consideração, onde os benefícios potenciais superam as perdas potenciais. 'A golden opportunity' refere-se a uma excelente chance que pode não surgir novamente. 'To take a gamble' significa correr um risco, muitas vezes com resultados incertos. 'To pay off' significa gerar um resultado positivo."
        },
        "mistakes": [
          {
            "en": "Incorrect: It's a risked calculation. (Correct: It's a calculated risk.)",
            "pt": "Incorreto: É um cálculo arriscado. (Correto: É um risco calculado.)"
          },
          {
            "en": "Incorrect: We took a chance that paid well. (Correct: We took a gamble that paid off.)",
            "pt": "Incorreto: Aproveitamos uma chance que pagou bem. (Correto: Arriscamos e valeu a pena.)"
          }
        ]
      }
    ],
