          "pt": "Assunto: Implementação do Novo Software de Gerenciamento de Projetos. Prezada Brenda, Escrevo para informar que o novo software de gerenciamento de projetos, 'TaskFlow Pro', está programado para ser implementado no próximo mês. Acreditamos que ele irá aumentar significativamente a produtividade e colaboração da nossa equipe."
