    "grammar": [
      {
        "title": {
          "en": "Ellipsis and Substitution for Natural, Concise Spoken English",
          "pt": "Elipse e Substituição para um Inglês Falado Natural e Conciso"
        },
        "examples": [
          {
            "en": "I'd love to, but I can't. (I'd love to *come*, but I can't *come*.)",
            "pt": "Eu adoraria, mas não posso. (Eu adoraria *vir*, mas não posso *vir*.)"
          },
          {
            "en": "She hasn't decided yet, but I think she will. (She hasn't decided yet, but I think she will *decide*.)",
            "pt": "Ela ainda não decidiu, mas acho que ela vai. (Ela ainda não decidiu, mas acho que ela vai *decidir*.)"
          },
          {
            "en": "Are you going to the conference? I might be. (I might be *going to the conference*.)",
            "pt": "Você vai à conferência? Eu talvez vá. (Eu talvez *vá à conferência*.)"
          }
        ],
        "rule": {
          "en": "Ellipsis is the omission of words, usually at the end of a clause, that are not necessary to the meaning because they can be understood from the context. Substitution involves using a pro-form (like 'do so', 'one', 'some', 'so', 'not', 'that') to replace a longer phrase or clause, avoiding repetition. Both techniques make speech and writing more natural, concise, and efficient.",
          "pt": "Elipse é a omissão de palavras, geralmente no final de uma oração, que não são necessárias para o significado porque podem ser entendidas a partir do contexto. Substituição envolve o uso de uma pró-forma (como 'do so', 'one', 'some', 'so', 'not', 'that') para substituir uma frase ou oração mais longa, evitando a repetição. Ambas as técnicas tornam a fala e a escrita mais naturais, concisas e eficientes."
        },
        "mistakes": [
          {
            "en": "Repeating full phrases instead of using ellipsis or substitution: 'Are you coming to the party?' 'Yes, I am coming to the party.' (Should be: 'Yes, I am.')",
            "pt": "Repetir frases completas em vez de usar elipse ou substituição: 'Você vem à festa?' 'Sim, eu venho à festa.' (Correto seria: 'Sim, eu venho.')"
          },
          {
            "en": "Incorrect use of substitution words: 'I don't like this app, but I need one.' (If 'one' refers to 'this app', it's wrong; 'it' would be more appropriate or clarify what 'one' refers to).",
            "pt": "Uso incorreto de palavras de substituição: 'Não gosto deste aplicativo, mas preciso de um.' (Se 'um' se refere a 'este aplicativo', está errado; 'ele' seria mais apropriado ou clarificar a que 'um' se refere)."
          }
        ]
      }
    ],
