        "pt": "Imagine que sua empresa precisa de uma nova solução tecnológica (por exemplo, um novo aplicativo, uma atualização de software, uma plataforma de gerenciamento de dados) para resolver um problema específico. Escreva um e-mail formal (150-200 palavras) para seu gerente propondo esta solução. Em seu e-mail, você deve: \n1. Declarar claramente o problema e a solução proposta. \n2. Usar pelo menos 5 dos novos itens de vocabulário de tecnologia. \n3. Incorporar pelo menos 2 expressões de escrita formal. \n4. Demonstrar uso eficaz de elipse e/ou substituição para concisão."
