    "grammar": [
      {
        "title": {
          "en": "Nuanced Vocabulary for Precise Emotional and Analytical Expression",
          "pt": "Vocabulário Nuanceado para Expressão Emocional e Analítica Precisa"
        },
        "examples": [
          {
            "en": "I'm *somewhat skeptical* about this approach, rather than simply 'I doubt it'.",
            "pt": "Estou *um tanto cético* sobre esta abordagem, em vez de apenas 'Eu duvido'."
          },
          {
            "en": "The results were *mildly disappointing*, not 'very bad'.",
            "pt": "Os resultados foram *ligeiramente decepcionantes*, não 'muito ruins'."
          },
          {
            "en": "She seemed *rather hesitant* to agree, instead of 'she didn't want to agree'.",
            "pt": "Ela parecia *bastante hesitante* em concordar, em vez de 'ela não queria concordar'."
          }
        ],
        "rule": {
          "en": "Use adverbs like 'somewhat', 'rather', 'mildly', 'slightly', 'utterly', 'highly', 'deeply' with adjectives or verbs to express feelings or opinions with greater precision and subtlety. This avoids overly strong or vague statements, allowing for a more sophisticated and analytical communication style. It's often used to soften criticism, express a degree of uncertainty, or emphasize a point without being absolute.",
          "pt": "Use advérbios como 'somewhat' (um tanto), 'rather' (bastante), 'mildly' (ligeiramente), 'slightly' (ligeiramente), 'utterly' (totalmente), 'highly' (altamente), 'deeply' (profundamente) com adjetivos ou verbos para expressar sentimentos ou opiniões com maior precisão e sutileza. Isso evita declarações excessivamente fortes ou vagas, permitindo um estilo de comunicação mais sofisticado e analítico. É frequentemente usado para suavizar críticas, expressar um grau de incerteza ou enfatizar um ponto sem ser absoluto."
        },
        "mistakes": [
          {
            "en": "Instead of 'I think it's bad', try 'I'm *rather concerned* about it'.",
            "pt": "Em vez de 'Acho que é ruim', tente 'Estou *bastante preocupado* com isso'."
          },
          {
            "en": "Avoid 'It's very important' and use 'It's *utterly crucial*' for emphasis.",
            "pt": "Evite 'É muito importante' e use 'É *totalmente crucial*' para dar ênfase."
          }
        ]
      }
    ],
