    "grammar": [
      {
        "title": {
          "en": "Discourse markers for academic argumentation",
          "pt": "Marcadores discursivos para argumentação acadêmica"
        },
        "examples": [
          {
            "en": "It could be argued that traditional teaching methods are still highly effective for foundational subjects.",
            "pt": "Poderia-se argumentar que os métodos de ensino tradicionais ainda são altamente eficazes para matérias fundamentais."
          },
          {
            "en": "This raises the question of how we assess skills that are difficult to quantify, like creativity.",
            "pt": "Isso levanta a questão de como avaliamos habilidades difíceis de quantificar, como a criatividade."
          },
          {
            "en": "It could be argued that the current grading system discourages interdisciplinary research.",
            "pt": "Poderia-se argumentar que o atual sistema de notas desencoraja a pesquisa interdisciplinar."
          }
        ],
        "rule": {
          "en": "'It could be argued that...' introduces a potential argument or perspective, suggesting that a point is debatable or one of several viewpoints. 'This raises the question of...' introduces an important question or issue that naturally follows from a previous statement, often implying a challenge or an area for further discussion.",
          "pt": "'It could be argued that...' introduz um argumento ou perspectiva potencial, sugerindo que um ponto é debatível ou uma das várias opiniões. 'This raises the question of...' introduz uma questão importante ou um problema que naturalmente decorre de uma afirmação anterior, muitas vezes implicando um desafio ou uma área para discussão posterior."
        },
        "mistakes": [
          {
            "en": "Incorrect: It argues that students need more support. (This is too direct; use 'It could be argued...')",
            "pt": "Incorreto: It argues that students need more support. (Isso é muito direto; use 'It could be argued...')"
          },
          {
            "en": "Incorrect: This question is raised of student wellbeing. (Incorrect phrasing; use 'This raises the question of...')",
            "pt": "Incorreto: This question is raised of student wellbeing. (Fraseado incorreto; use 'This raises the question of...')"
          }
        ]
      }
    ],
